package app.loveu;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.location.*;import android.os.*;import java.util.*;import java.util.concurrent.*;import java.lang.ref.WeakReference;
public final class LocationCapture {
 private static final ThreadPoolExecutor GEOCODER_WORKER=new ThreadPoolExecutor(1,1,0,TimeUnit.MILLISECONDS,new SynchronousQueue<Runnable>(),r->{Thread t=new Thread(r,"LoveUAddress");t.setDaemon(true);return t;},new ThreadPoolExecutor.AbortPolicy());
 public interface Callback {void onResult(Result result);}
 public static final class Result {
  public final String label;public final double latitude,longitude;public final float accuracy;public final long timestamp;public final boolean addressResolved;
  Result(Location l,boolean precise,String address){latitude=precise?l.getLatitude():Math.round(l.getLatitude()*100.0)/100.0;longitude=precise?l.getLongitude():Math.round(l.getLongitude()*100.0)/100.0;accuracy=precise?l.getAccuracy():Math.max(1500,l.getAccuracy());timestamp=l.getTime();addressResolved=address!=null&&!address.trim().isEmpty();label=addressResolved?address:String.format(Locale.CHINA,"%s坐标 %.5f, %.5f（精度约 %d 米）",precise?"":"大致",latitude,longitude,Math.round(accuracy));}
 }
 public static void capture(Activity a,Callback c){capture(a,false,c);}
 public static void capture(Activity a,boolean p,Callback c){capture(a,p,()->!a.isFinishing()&&!a.isDestroyed(),c);}
 public static void capture(Activity a,boolean p,java.util.function.BooleanSupplier active,Callback c){a.runOnUiThread(()->{if(!active.getAsBoolean()||a.isFinishing()||a.isDestroyed()||a.checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED){c.onResult(null);return;}new Request(a,p&&a.checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED,active,c).start();});}
 static String addressLabel(Address a,boolean precise){LinkedHashSet<String> parts=new LinkedHashSet<>();String[] fields=precise?new String[]{a.getAdminArea(),a.getLocality(),a.getSubLocality(),a.getThoroughfare(),a.getSubThoroughfare(),a.getFeatureName()}:new String[]{a.getAdminArea(),a.getLocality(),a.getSubLocality()};for(String part:fields)if(part!=null&&!part.trim().isEmpty()&&!part.equals(a.getCountryName())&&!part.equals("中国"))parts.add(part.trim());String line=a.getMaxAddressLineIndex()>=0?a.getAddressLine(0):null;boolean street=a.getThoroughfare()!=null||a.getSubThoroughfare()!=null;if(precise&&line!=null&&line.trim().length()>6&&!line.trim().equals(a.getCountryName())){return parts.size()>1&&line.length()<String.join("",parts).length()?String.join("",parts):line;}if(parts.isEmpty())return null;return (precise&&street?"":"区域（未解析到街道）：")+String.join("",parts);}
 private static final class Request implements LocationListener,Application.ActivityLifecycleCallbacks {
  final Activity activity;final boolean precise;final java.util.function.BooleanSupplier active;final Callback callback;final LocationManager manager;final Handler handler=new Handler(Looper.getMainLooper());final long started=SystemClock.elapsedRealtimeNanos();boolean done,geocoding;Location fix;Future<?> addressJob;
  Result fallback(){return fix==null?null:new Result(fix,precise,null);}final Runnable timeout=()->finish(fallback());final Runnable addressTimeout=()->finish(fallback());
  Request(Activity a,boolean p,java.util.function.BooleanSupplier current,Callback c){activity=a;precise=p;active=current;callback=c;manager=(LocationManager)a.getSystemService(Context.LOCATION_SERVICE);}
  boolean alive(){return active.getAsBoolean()&&!activity.isFinishing()&&!activity.isDestroyed();}
  void start(){activity.getApplication().registerActivityLifecycleCallbacks(this);handler.postDelayed(timeout,25000);handler.postDelayed(fixTimeout,20000);try{boolean requested=false;if(manager!=null){String[] providers=precise?new String[]{LocationManager.GPS_PROVIDER,LocationManager.NETWORK_PROVIDER}:new String[]{LocationManager.NETWORK_PROVIDER};for(String provider:providers)if(manager.isProviderEnabled(provider)){manager.requestLocationUpdates(provider,0,0,this,Looper.getMainLooper());requested=true;}}if(!requested)finish(null);}catch(SecurityException|IllegalArgumentException e){finish(null);}}
  final Runnable fixTimeout=()->{if(!geocoding){if(fix==null)finish(null);else resolveCoordinates();}};
  void stopUpdates(){if(manager!=null)try{manager.removeUpdates(this);}catch(SecurityException ignored){}}
  void finish(Result r){if(done)return;done=true;stopUpdates();handler.removeCallbacks(timeout);handler.removeCallbacks(fixTimeout);handler.removeCallbacks(addressTimeout);if(addressJob!=null)addressJob.cancel(true);activity.getApplication().unregisterActivityLifecycleCallbacks(this);callback.onResult(alive()?r:null);}
  public void onLocationChanged(Location l){if(done||geocoding||l.getElapsedRealtimeNanos()<started||!l.hasAccuracy()||!Float.isFinite(l.getAccuracy())||l.getAccuracy()<0)return;if(!alive()){finish(null);return;}if(fix!=null&&l.getAccuracy()>fix.getAccuracy())return;fix=new Location(l);if(precise&&l.getAccuracy()>100)return;resolveCoordinates();} void resolveCoordinates(){geocoding=true;stopUpdates();handler.removeCallbacks(fixTimeout);handler.postDelayed(addressTimeout,5000);if(!Geocoder.isPresent()){finish(new Result(fix,precise,null));return;}Geocoder coder=new Geocoder(activity.getApplicationContext(),Locale.CHINA);Result coords=new Result(fix,precise,null);try{if(Build.VERSION.SDK_INT>=33){coder.getFromLocation(coords.latitude,coords.longitude,1,new Geocoder.GeocodeListener(){public void onGeocode(List<Address> addresses){handler.post(()->resolved(addresses));}public void onError(String error){handler.post(()->finish(new Result(fix,precise,null)));}});}else{addressJob=lookupLegacy(coder,coords.latitude,coords.longitude,new WeakReference<>(this),handler);}}catch(Exception e){finish(new Result(fix,precise,null));}}
  private static Future<?> lookupLegacy(Geocoder coder,double latitude,double longitude,WeakReference<Request> request,Handler main){return GEOCODER_WORKER.submit(()->{List<Address> list=null;try{list=coder.getFromLocation(latitude,longitude,1);}catch(Exception ignored){}final List<Address> result=list;main.post(()->{Request current=request.get();if(current!=null)current.resolved(result);});});}
  void resolved(List<Address> addresses){if(done)return;if(!alive()){finish(null);return;}String label=null;if(addresses!=null&&!addresses.isEmpty()){Address a=addresses.get(0);label=addressLabel(a,precise);}finish(new Result(fix,precise,label));}
  public void onStatusChanged(String p,int s,Bundle b){}public void onProviderEnabled(String p){}public void onProviderDisabled(String p){}
  public void onActivityPaused(Activity a){if(a==activity)finish(null);}public void onActivityDestroyed(Activity a){if(a==activity)finish(null);}public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}
 }
}


